package com.example.aetherlauncher

import android.graphics.BitmapFactory
import android.util.Base64
import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.size
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.asImageBitmap

private const val AETHER_LOGO_WEBP = ""

@Composable
fun AetherLogo(modifier: Modifier = Modifier) {
    val bitmap = remember { BitmapFactory.decodeByteArray(Base64.decode(AETHER_LOGO_WEBP, Base64.DEFAULT), 0, Base64.decode(AETHER_LOGO_WEBP, Base64.DEFAULT).size) }
    Image(bitmap = bitmap.asImageBitmap(), contentDescription = "Aether Launcher", modifier = modifier)
}
